static int bk7258_wdt_keepalive(struct watchdog_lowerhalf_s *lower)
{
  /* ★DIAG: prove NuttX automonitor/tick actually drives keepalive (every
   * CONFIG_WATCHDOG_AUTOMONITOR_PING_INTERVAL=4 s).  If "KA#" never appears
   * while "WD1" did, the work-queue/tick is not scheduling → feed never
   * called → WDT resets.  If "KA#" appears but reset still happens, feed is
   * called but doesn't reach hardware.  Freestanding poll UART1, safe in any
   * context. Run-length encode to a single hex digit so each keepalive is 3
   * bytes ("KA" + nibble) and the nibble wraps, minimising UART traffic. */
  extern void arm_lowputc(char ch);
  static int s_ka_seq = 0;
  int n = (s_ka_seq++) & 0xf;
  arm_lowputc('K'); arm_lowputc('A');
  arm_lowputc(n < 10 ? '0' + n : 'A' + (n - 10));
  return (bk_wdt_feed() == BK_OK) ? OK : -EIO;
}

