  /* ★DIAG (one-shot, revert after): distinguish three SysTick/fail modes for
   * the "WD1 armed but KA* never fires" reset.  Uses the freestanding poll
   * UART1 putchar so output survives even if the scheduler is dead.
   *
   *   "ST" + 3 bits of SYST_CSR (ENABLE,TICKINT,CLKSOURCE) + 'M'/'F'
   *     M = SYST_CVR changed between two reads (ticker is counting)
   *     F = SYST_CVR frozen (clock source dead / SysTick disabled)
   */
  {
    volatile uint32_t *csr = (volatile uint32_t *)0xe000e010u;
    volatile uint32_t *cvr = (volatile uint32_t *)0xe000e018u;

    extern void arm_lowputc(char ch);
    #define DB(c) arm_lowputc(c)

    uint32_t v1 = *cvr;
    for (volatile int d = 0; d < 800000; d++) { }
    uint32_t v2 = *cvr;

    uint32_t c = *csr;
    DB('S'); DB('T');
    DB('0' + (c & 1u));                 /* bit0 ENABLE */
    DB('0' + ((c >> 1) & 1u));          /* bit1 TICKINT */
    DB('0' + ((c >> 2) & 1u));          /* bit2 CLKSOURCE */
    DB((v1 != v2) ? 'M' : 'F');
    DB('\r'); DB('\n');
    #undef DB
  }

  /* ★DIAG scheduler probe: a NuttX thread that ticks every ~1 s.  If "T0"
   * "T1" ... appear, the SysTick ISR dispatches into the scheduler and
   * thread context switches work → the WDT feed worker should also run.
   * If nothing appears after several seconds, the scheduler never starts
   * (SysTick ISR not dispatched / PendSV dead / automonitor never armed).
   */
  {
    extern int task_create(const char *name, int priority, int stack_size,
                           main_t entry, const char *argv[]);
    extern void arm_lowputc(char ch);

    static int s_tick = 0;
    const char *args[] = { "dprobe", NULL };

    /* tiny entry: prints "T" + hex of an incrementing counter each second */
    /* We can't use sleep() safely here directly; use nxsig_sleep/usleep. */
    int probe_main(int argc, char *argv[])
    {
      int n = 0;
      for (;;)
        {
          arm_lowputc('T');
          int x = (n++) & 0xf;
          arm_lowputc(x < 10 ? '0' + x : 'A' + (x - 10));
          arm_lowputc('\r');
          nxsig_sleep(1);   /* 1 s, scheduler-driven */
        }
      return 0;
    }

    (void)task_create("dprobe", 100, 1024, probe_main,
                      (const char *const *)args);
  }

  return 0;
}

