void bk7258_hardfault_handler(void)
{
  /* ★DIAG: disable ALL watchdogs so CPU stays alive in this handler.
   * After HF appears on UART1, use JLink Commander:
   *   r        (reset — now CPU halts at bootloader, not mid-HF)
   *   h        (halt)
   *   mem32 0xE000ED28,1   (CFSR — but cleared by reset...)
   *
   * Better: don't reset. After HF, JLink should be able to halt
   * the CPU now that WDTs are off:
   *   h
   *   regs
   *   mem32 0xE000ED28,1
   */

  /* Kill APB WDT (wdt_reg.h: write any value without key → disarm) */
  *(volatile uint32_t *)0x44800010u = 0u;   /* WDT_APB_CTRL = 0 */

  /* Kill AON WDT */
  *(volatile uint32_t *)0x44000600u = 0u;   /* WDT_AON_CTRL = 0 */

  /* Kill SysTick (stop it from firing more interrupts) */
  *(volatile uint32_t *)0xE000E010u = 0u;   /* SYST_CSR = 0 */

  bk7258_fault_putc('H');
  bk7258_fault_putc('F');

  /* Park forever — WDTs are off, CPU won't reset.
   * JLink can halt at any time via: h / regs / mem32
   */
  for (; ; )
    {
    }
}

